param([string]$RosterPath,[switch]$OwnerAuthorized,[string]$Root=(Join-Path $env:LOCALAPPDATA 'G6\RabbitMQ\g5-onboarding'),[string]$AdminKeyPath=(Join-Path $env:USERPROFILE '.ssh\g6_oracle'))
$ErrorActionPreference='Stop'
if(-not $OwnerAuthorized){if([string]::IsNullOrWhiteSpace($RosterPath)-or-not(Test-Path -LiteralPath $RosterPath -PathType Leaf)){throw 'Supply formal G5 homologation roster or explicitly pass -OwnerAuthorized for this controlled operator run.'};$roster=@(Import-Csv -LiteralPath $RosterPath);if($roster.Count-eq 0-or@($roster|Where-Object {$_.EstadoHomologacion -cne 'HOMOLOGADO'-or[string]::IsNullOrWhiteSpace($_.ReferenciaHomologacion)-or[string]::IsNullOrWhiteSpace($_.Nombre)-or$_.Login-notmatch'^g5_[a-z0-9][a-z0-9_-]{1,30}$'}).Count-gt 0-or@($roster.Login|Sort-Object -Unique).Count-ne $roster.Count){throw 'RabbitMQ activation requires a named recipient roster fully homologated with documentary reference.'}}
if(-not(Test-Path $AdminKeyPath)){throw 'Administrator SSH key was not found.'}
$vaultPath=Join-Path $Root 'rabbitmq-credential.dpapi.xml';if(Test-Path $vaultPath){throw 'A G5 RabbitMQ credential already exists; refusing to rotate or overwrite it.'}
$bytes=[Security.Cryptography.RandomNumberGenerator]::GetBytes(32);$password=[Convert]::ToBase64String($bytes).TrimEnd('=').Replace('+','-').Replace('/','_');[Security.Cryptography.CryptographicOperations]::ZeroMemory($bytes)
$remote='ubuntu@157.137.205.218';$remoteScript='/tmp/g5-rabbitmq-provision.sh';$scriptPath=Join-Path $PSScriptRoot 'provision-g5-ventas-rabbit-user.sh'
& scp -i $AdminKeyPath -o IdentitiesOnly=yes -o BatchMode=yes $scriptPath "${remote}:${remoteScript}";if($LASTEXITCODE-ne 0){throw 'Could not send non-secret G5 provisioner.'}
$psi=[Diagnostics.ProcessStartInfo]::new();$psi.FileName='ssh';foreach($a in @('-i',$AdminKeyPath,'-o','IdentitiesOnly=yes','-o','BatchMode=yes',$remote,"sudo -n bash $remoteScript")){[void]$psi.ArgumentList.Add($a)};$psi.UseShellExecute=$false;$psi.RedirectStandardInput=$true;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
$p=[Diagnostics.Process]::new();$p.StartInfo=$psi;[void]$p.Start();$out=$p.StandardOutput.ReadToEndAsync();$err=$p.StandardError.ReadToEndAsync();$p.StandardInput.WriteLine($password);$p.StandardInput.Close();$p.WaitForExit()
try{if($p.ExitCode-ne 0){$safeError=$err.GetAwaiter().GetResult() -replace [regex]::Escape($password),'[REDACTED]' -replace '[A-Za-z0-9_-]{32,}','[REDACTED]';throw "RabbitMQ identity provisioning failed ($($p.ExitCode)); $safeError"};$secure=ConvertTo-SecureString $password -AsPlainText -Force;Export-Clixml -InputObject $secure -LiteralPath $vaultPath;$secure.Dispose();$owner=[Security.Principal.WindowsIdentity]::GetCurrent().Name;icacls $vaultPath /inheritance:r /grant:r "$owner`:(F)" 'NT AUTHORITY\SYSTEM:(F)'|Out-Null;$status=if($OwnerAuthorized){'under explicit operator authorization; formal G5 homologation remains pending'}else{'under the documented homologated roster'};Write-Output "g5_ventas provisioned $status and saved in the local DPAPI vault."}finally{$password=$null;try{& ssh -i $AdminKeyPath -o IdentitiesOnly=yes -o BatchMode=yes $remote "rm -f $remoteScript" 2>$null|Out-Null}catch{}}
